"""Build three standalone, static design concepts. OwnerRez booking widget attached."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
mark='<svg viewBox="0 0 64 40" aria-hidden="true"><path d="M2 36 23 5l12 18 8-12 19 25M15 17l8 5 5-7M36 21l7 4 5-6" fill="none" stroke="currentColor" stroke-width="2"/></svg>'

def img(n,alt,cls='',eager=False):
 return f'<img class="{cls}" src="assets/photo-{n:02d}.webp" alt="{alt}" loading="{"eager" if eager else "lazy"}" width="1440" height="1080">'
def photo(n,alt,cls=''):
 return f'<button class="photo {cls}" data-photo="assets/photo-{n:02d}.webp" data-caption="{alt}" aria-label="Enlarge: {alt}">{img(n,alt)}</button>'
def header(theme):
 return f'''<header class="site-header"><a class="brand" href="{theme}.html">{mark}<span>RED HAWK <b>2240</b><small>KEYSTONE, COLORADO</small></span></a><nav aria-label="Main navigation"><a href="#stay">The stay</a><a href="#explore">Explore</a><a href="#gallery">Photos</a><a class="nav-book" href="#book">Plan your stay <span>↗</span></a></nav></header>'''
def booking():
 return '''<form class="booking-form" action="https://app.ownerrez.com/widgets/f13cd4d5594545a4b410a094355b8b4d" method="get"><input type="hidden" name="view" value="form"><input type="hidden" name="propertyKey" value="bc7244c04d284b70baab4dede8d52fb0"><label>CHECK IN<input type="date" name="or_arrival" required aria-label="Check-in date"></label><label>CHECK OUT<input type="date" name="or_departure" required aria-label="Check-out date"></label><label>GUESTS<select name="or_guests" aria-label="Guests">'''+''.join(f'<option value="{n}" {"selected" if n==2 else ""}>{n} guest{"s" if n>1 else ""}</option>' for n in range(1,7))+'''</select></label><button class="button" type="submit">Check availability <span>↗</span></button><p class="date-error" role="alert"></p></form><p class="booking-handoff">Check availability, view pricing and book your stay securely.</p>'''
def gallery():
 return '<section class="gallery-section wrap" id="gallery"><div class="section-top"><div><p class="eyebrow">A CLOSER LOOK</p><h2>Picture yourself here.</h2></div><p>Your own mountain home.<br>A few very good places to unwind.</p></div><div class="gallery-grid">'+''.join(photo(n,a) for n,a in [(1,'Bright living room with teal sofa and mountain light'),(9,'King bedroom with an ensuite bathroom'),(12,'Queen bedroom with large windows'),(14,'Fully equipped kitchen and breakfast counter'),(5,'Private balcony framed by aspen trees'),(24,'Shared outdoor hot tub with mountain views')])+'</div><p class="gallery-note">Select a photo to take a closer look.</p></section>'
def faq():
 return '''<section class="faq wrap"><div><p class="eyebrow">BEFORE YOU PACK</p><h2>A few good<br>things to know.</h2></div><div><details><summary>How close is the gondola?</summary><p>Red Hawk Lodge sits on the edge of River Run Village for a slightly quieter stay, approximately 900 feet from the River Run Gondola.</p></details><details><summary>Where will everyone sleep?</summary><p>A king bedroom, a queen bedroom and a fold-away Murphy bed give your group room to settle in. The condo accommodates up to six overnight guests, with two full bathrooms.</p></details><details><summary>Is parking included?</summary><p>One space in the heated underground garage is included. An elevator serves the building. Additional vehicles need separate parking arrangements.</p></details><details><summary>Are the pool and hot tubs private?</summary><p>The heated pool, two hot tubs, steam room, fitness center and game room are shared Red Hawk Lodge amenities, subject to building access and maintenance.</p></details><details><summary>Can we bring pets?</summary><p>The current house rules do not allow pets or smoking. Please review the full rules and current conditions before reserving.</p></details></div></section>'''
def footer(theme,num):
 return f'''<footer class="site-footer wrap"><a class="brand" href="{theme}.html">{mark}<span>RED HAWK <b>2240</b><small>YOUR PLACE IN KEYSTONE</small></span></a><div><a href="https://www.airbnb.com/rooms/45842208" target="_blank" rel="noopener">View Airbnb listing ↗</a></div><p>Red Hawk Lodge · River Run · Keystone, Colorado</p></footer><aside class="concept-bar" aria-label="Design concepts"><a href="index.html">← All concepts</a><span>CONCEPT {num} / 03</span><a href="{'gatherings' if num=='01' else 'summit' if num=='02' else 'alpine'}.html">Next design →</a></aside>'''
def dialogs():
 return '''<dialog class="lightbox"><button class="dialog-close" aria-label="Close photo">×</button><img alt=""><p></p><div class="lightbox-controls"><button data-direction="-1" aria-label="Previous photo">← Previous</button><button data-direction="1" aria-label="Next photo">Next →</button></div></dialog>'''
def shell(theme,title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} | Red Hawk 2240</title><meta name="description" content="A Red Hawk 2240 direct-booking design concept, featuring the actual Keystone condo."><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"></head><body class="{theme}"><a class="skip-link" href="#main">Skip to content</a>{header(theme)}<main id="main">{body}</main>{footer(theme,{'alpine':'01','gatherings':'02','summit':'03'}[theme])}{dialogs()}<script src="site.js"></script></body></html>'''

alpine=f'''<section class="alpine-hero">{img(0,'Heated pool and sunlit mountains at Red Hawk Lodge','hero-image',True)}<div class="hero-shade"></div><div class="alpine-hero-copy wrap"><p class="eyebrow">RED HAWK LODGE · RIVER RUN VILLAGE</p><h1>A little closer<br>to <em>the mountains.</em></h1><p>Your own space to slow down.<br>And every reason to head outside.</p><a class="hero-link" href="#stay">Discover your stay <span>↓</span></a></div><span class="hero-coordinate">KEYSTONE, COLORADO &nbsp; / &nbsp; FOUR SEASONS, ONE GOOD PLACE</span></section><section class="alpine-book wrap" id="book"><p class="eyebrow">MAKE ROOM FOR A GETAWAY</p>{booking()}</section><div class="facts wrap"><span><b>6</b> guests</span><span><b>2</b> bedrooms</span><span><b>2</b> bathrooms</span><span><b>~900 ft</b> to the gondola</span></div><section class="editorial wrap" id="stay"><div><p class="eyebrow">MOUNTAIN DAYS. FIRESIDE NIGHTS.</p><h2>More space.<br>Less rush.<br><em>All yours.</em></h2><p>A bright, generously sized condo for the people you love traveling with. Spread out over breakfast, linger by the fireplace, and let the mountains set the pace.</p><a class="underlink" href="#gallery">Step inside ↗</a></div><figure>{photo(1,'Contemporary living room with teal sofa and warm wood finishes')}<figcaption>Not the usual mountain cabin. A little more you.</figcaption></figure></section><section class="amenity-story" id="explore"><div class="amenity-photo">{img(24,'Outdoor hot tub surrounded by aspens and mountain scenery')}</div><div><p class="eyebrow">THE ART OF DOING A LITTLE LESS</p><h2>First chair.<br>Last soak.</h2><p>A short walk to River Run. A long soak back at the lodge. The best mountain days leave room for both.</p><ul class="amenity-list"><li>Year-round heated pool & two hot tubs</li><li>One heated underground parking space</li><li>Private balcony & mountain views</li><li>Shared steam room & fitness center</li></ul></div></section>{gallery()}{faq()}<section class="closing wrap"><p class="eyebrow">MAKE IT A MOUNTAIN KIND OF WEEKEND</p><h2>Your next deep breath<br>starts <em>here.</em></h2><a class="button" href="#book">Plan your stay ↗</a></section>'''

family=f'''<section class="family-hero wrap"><div class="family-heading"><p class="eyebrow">A GOOD PLACE TO GET EVERYONE TOGETHER</p><h1>Big mountain days.<br><em>Little moments</em><br>you’ll keep.</h1><p>Welcome to Red Hawk 2240. Your bright, happy home base for six in Keystone’s River Run neighborhood.</p><a class="button" href="#book">Let’s get away <span>↗</span></a><span class="hand-note">Bring your favorite people.</span></div><div class="family-collage">{img(1,'Sunny living room ready for a family mountain getaway','collage-main',True)}{img(3,'Dining table and colorful chairs for gathering together','collage-small',True)}<div class="round-stamp">SLEEP SIX<br><span>MAKE MEMORIES</span><br>STAY AWHILE</div></div></section><div class="family-ticker"><span>TWO BEDROOMS</span><span>✳</span><span>POOL & HOT TUBS</span><span>✳</span><span>ROOM FOR SIX</span><span>✳</span><span>RIVER RUN, KEYSTONE</span><span>✳</span></div><section class="family-plan wrap" id="book"><div><p class="eyebrow">LESS PLANNING. MORE LOOKING FORWARD.</p><h2>When are we going?</h2></div>{booking()}</section><section class="family-stay wrap" id="stay"><div class="section-top"><div><p class="eyebrow">UNPACK. EXHALE. MAKE YOURSELF AT HOME.</p><h2>Room for the whole crew.</h2></div><p>Two bedrooms. Two baths.<br>Zero need to crowd around one sofa.</p></div><div class="family-room-grid"><article>{photo(9,'Primary king bedroom with navy wall and warm linens')}<span class="room-number">01 / SLEEP IN</span><h3>A king-size kind of morning.</h3><p>A primary bedroom with an ensuite bath, plus a queen bedroom and a fold-away Murphy bed for the rest of your crew.</p></article><article>{photo(3,'Dining area with room to gather for meals and board games')}<span class="room-number">02 / GATHER ROUND</span><h3>One more round?</h3><p>A dining table for six or more, a stocked board-game shelf and a full kitchen. The best nights don’t always need a reservation.</p></article><article>{photo(0,'Shared heated pool at Red Hawk Lodge overlooking the mountains')}<span class="room-number">03 / JUST ADD WATER</span><h3>The kids have a plan.</h3><p>A heated pool for another splash. Two shared hot tubs for a well-earned soak. Everybody wins.</p></article></div></section><section class="family-outdoors" id="explore"><div>{img(54,'Shops and restaurants in Keystone River Run Village')}</div><div><p class="eyebrow">OUT THE DOOR & INTO IT</p><h2>Park the car.<br>Pick your adventure.</h2><p>Walk roughly 900 feet to the gondola and River Run Village. Ski days, bike rides, village strolls. Or simply a very good afternoon on the balcony.</p><div class="family-mini-facts"><span>❋<b>Winter</b>Ski & ride</span><span>☀<b>Summer</b>Hike & explore</span><span>⌂<b>All year</b>Come together</span></div></div></section>{gallery()}{faq()}<section class="family-closing wrap"><p class="eyebrow">SAME PEOPLE. NEW FAVORITE MEMORIES.</p><h2>See you in<br><em>the mountains.</em></h2><a class="button" href="#book">Find your family getaway ↗</a></section>'''

summit=f'''<section class="summit-hero">{img(50,'Snow-covered Keystone slopes and mountain panorama','hero-image',True)}<div class="hero-shade"></div><div class="summit-copy wrap"><p class="eyebrow">RED HAWK 2240 / KEYSTONE, CO</p><h1>OUT THERE.<br><span>RIGHT HERE.</span></h1><div class="summit-hero-bottom"><p>Mountain adventures on your doorstep.<br>A proper home to come back to.</p><a class="circle-link" href="#book" aria-label="Plan your stay">↗</a></div></div><div class="summit-caption">YOUR BASECAMP AT RIVER RUN &nbsp; · &nbsp; STAY CLOSE. GO FAR.</div></section><section class="summit-book" id="book"><div class="wrap"><p class="eyebrow">NEXT STOP: KEYSTONE</p>{booking()}</div></section><div class="summit-stat-grid wrap"><div><b>06</b><span>GUESTS, ONE GREAT TRIP</span></div><div><b>02</b><span>BEDROOMS + TWO BATHS</span></div><div><b>900<small>FT</small></b><span>APPROX. WALK TO THE GONDOLA</span></div></div><section class="summit-stay wrap" id="stay"><div class="summit-heading"><p class="eyebrow">THE BASECAMP / 01</p><h2>GO BIG OUTSIDE.<br><span>GET COMFORTABLE INSIDE.</span></h2></div><div class="summit-room">{photo(8,'Fireplace and living room for relaxing after a day in the mountains')}<div><p class="eyebrow">BUILT FOR THE IN-BETWEEN</p><h3>The best part<br>of coming back.</h3><p>Boots off. Fireplace on. A generous living space, a full kitchen and a private balcony make this more than somewhere to crash.</p><ul class="amenity-list"><li>King bedroom + queen bedroom + Murphy bed</li><li>Heated garage parking for one car</li><li>Private ski locker at the lodge</li><li>Shared pool, hot tubs & steam room</li></ul><a class="underlink" href="#gallery">Tour the space ↗</a></div></div></section><section class="summit-explore wrap" id="explore"><div class="section-top"><div><p class="eyebrow">THE PLAYGROUND / 02</p><h2>NO OFF-SEASON.</h2></div><div class="season-tabs" role="group" aria-label="Explore by season"><button class="active" data-season="winter" aria-pressed="true">Winter</button><button data-season="summer" aria-pressed="false">Summer</button></div></div><div class="season-panel">{img(50,'Snowy slopes and mountain views above Keystone','season-image')}<div><p class="eyebrow season-label">MAKE TRACKS</p><h3 class="season-title">Chase the mountain.<br>Skip the drive.</h3><p class="season-text">Start with the short walk to River Run Gondola. Finish in a hot tub. Your ski-day routine just got an upgrade.</p><a class="underlink" href="#book">Make a plan ↗</a></div></div></section>{gallery()}{faq()}<section class="summit-closing wrap"><p class="eyebrow">GOOD DAYS START WITH A GOOD BASE</p><h2>GO FIND<br>YOUR <span>OUT THERE.</span></h2><a class="button" href="#book">Start your next trip ↗</a></section>'''
for theme,title,body in [('alpine','The Alpine Edit',alpine),('gatherings','The Gathering Place',family),('summit','Basecamp 2240',summit)]:
 (ROOT/f'{theme}.html').write_text(shell(theme,title,body))
(ROOT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#233f37"/><path d="m8 47 18-29 12 17 8-12 13 24" stroke="#f4efdf" stroke-width="3" fill="none"/></svg>')
print('Built three design concepts.')
